mapper.update:
UPDATE rx_dist_lock
SET holder = #{holder}, acquired_at = CURRENT_TIMESTAMP, expires_at = #{expiresAt}
WHERE lock_key = #{lockKey}
  AND (holder IS NULL OR expires_at IS NULL OR expires_at < CURRENT_TIMESTAMP)

mapper.select:
SELECT metric_name AS metricName, metric_value AS metricValue
FROM rx_metric
WHERE instance_id = #{instanceId}
  AND metric_name IN ('CPU', 'MEMORY', 'DISK', 'MSGW', 'LCKW')
  AND collect_time = (
      SELECT MAX(collect_time) FROM rx_metric
      WHERE instance_id = #{instanceId}
  )
